def checked_bytes(path, record):
    raw=Path(path).read_bytes()
    if (len(raw)!=record["bytes"] or len(raw)>=100000
            or hashlib.sha256(raw).hexdigest()!=record["sha256"]):
        raise ValueError("A complete pinned source/parameter identity changed: "+str(path))
    return raw


def checked_text(repo, record):
    return checked_bytes(Path(repo)/record["path"],record).decode("utf-8")


def whole_replace(text, before, after, count, label):
    if not isinstance(count,int) or count!=1 or text.count(before)!=count:
        raise ValueError("The full literal replacement scope changed: "+label)
    return text.replace(before,after)


def encode(value):
    return (json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+"\n").encode("utf-8")


def assert_output(raw, record):
    if (len(raw)!=record["bytes"] or len(raw)>=100000
            or hashlib.sha256(raw).hexdigest()!=record["sha256"]):
        raise ValueError("The complete reconstructed output differs: "+record["name"])


def reproduce(repo):
    original=checked_text(repo,DATA["parent_source"])
    original_ready_bytes=checked_bytes(Path(repo)/DATA["parent_ready"]["path"],DATA["parent_ready"])
    original_ready=json.loads(original_ready_bytes)
    checked_text(repo,DATA["required_current_proof"])
    value=original
    for item in DATA["whole_source_replacements"]:
        value=whole_replace(value,item["before"],item["after"],item["count"],item["label"])
    raw=value.encode("utf-8")
    assert_output(raw,DATA["output_source"])
    inverse=value
    for item in reversed(DATA["whole_source_replacements"]):
        inverse=whole_replace(inverse,item["after"],item["before"],item["count"],"inverse "+item["label"])
    if inverse!=original:
        raise ValueError("Whole inverse must recover every original parent byte")
    ready=json.loads(original_ready_bytes)
    old_values={}
    absent=[]
    for key,value in DATA["ready_top_level_replacements"].items():
        if key in ready:
            old_values[key]=ready[key]
        else:
            absent.append(key)
        ready[key]=value
    complete_ready=encode(ready)
    assert_output(complete_ready,DATA["output_ready"])
    recovered=json.loads(complete_ready)
    for key,value in old_values.items():
        recovered[key]=value
    for key in absent:
        del recovered[key]
    if recovered!=original_ready or encode(recovered)!=original_ready_bytes:
        raise ValueError("Whole inverse must recover every original ready value and byte")
    old_step=original_ready["steps"][0]
    new_step=ready["steps"][0]
    old_selectors=next(iter(old_step["summary"].values()))
    new_selectors=next(iter(new_step["summary"].values()))
    if (len(original_ready["steps"])!=1 or len(ready["steps"])!=1
            or len(old_step["args"])!=8 or len(new_step["args"])!=8
            or len(old_selectors)!=66 or new_selectors!=old_selectors):
        raise ValueError("Keep the entire one-step eight-argument/66-selector contract")
    changed=[i for i,(a,b) in enumerate(zip(old_step["args"],new_step["args"])) if a!=b]
    if changed!=[3,5] or new_step["args"][-2:]!=["--support-chunk-rows","4096"]:
        raise ValueError("Only the two declared current input/output paths change")
    return [(DATA["output_source"],raw),(DATA["output_ready"],complete_ready)]


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo",type=Path,required=True)
    parser.add_argument("--outdir",type=Path)
    parser.add_argument("--verify-existing",action="store_true")
    args=parser.parse_args()
    repo=args.repo.resolve()
    if args.verify_existing:
        if args.outdir is not None:
            raise ValueError("Choose one complete output mode")
    elif args.outdir is None:
        raise ValueError("A separate complete generated-output directory is required")
    outputs=reproduce(repo)
    protected=[(repo/DATA[key]["path"]).resolve() for key in
        ("parent_source","parent_ready","required_current_proof")]
    if not args.verify_existing:
        outdir=args.outdir.resolve()
        if any(outdir==path or outdir in path.parents for path in protected):
            raise ValueError("Output cannot contain a complete bound input")
        outdir.mkdir(parents=True,exist_ok=True)
    records=[]
    for record,raw in outputs:
        path=(repo/record["path"]) if args.verify_existing else (outdir/record["name"])
        if args.verify_existing or path.exists():
            actual=checked_bytes(path,record)
            if actual!=raw:
                raise ValueError("Every existing complete output byte must agree")
        else:
            with path.open("xb") as handle:
                handle.write(raw)
        checked_bytes(path,record)
        records.append(dict(path=str(path.resolve()),bytes=len(raw),
            sha256=hashlib.sha256(raw).hexdigest()))
    print(json.dumps(dict(schema=DATA["schema"],complete_source_and_parameter_outputs=records,
        full_inverse_source_and_ready_equal_original_parent=True,
        all_eight_arguments_and_66_selectors_preserved=True,
        original_mathematical_domains_and_budgets_retained=True,
        scientific_imports_or_execution=False,source_constructor_only=True),
        sort_keys=True,allow_nan=False))


if __name__=="__main__":
    main()
